// The generator of the job in plan.js. A participant of `hooked.note` is a function from { text, options } to a line of text; the job calls it through `fill.use`.
import fs from 'node:fs';

export const apiVersion = 1;

export function generate({ input, output, log, hooks, onInput }) {
  onInput(input);
  const text = fs.readFileSync(input, 'utf8').trim();
  fs.appendFileSync(log, 'ran\n');
  const notes = hooks['hooked.note'].map(fill => fill.use(note => note({ text, options: fill.options })));
  return { artifacts: [{ path: output, content: `/* Generated by @fixture/hooked. Do not edit. */\n${[text, ...notes].join('\n')}\n` }], manifestPaths: [], watchInputs: [input] };
}
